            undoAction->AddParam(new CActionParamSLONG(stat));
            undoEntry->AddAction(undoAction);
        }
    }
    if (dynamically)
        list->AddScrollingChildDynamicallyAndSetOffsets(entry);
    else
        list->AddScrollingChildAndSetOffsets(entry);
}

